from urduhelp import *
c=cell
def H(s,ur,en,ps): add(s,f'h{len(s["paras"])+1}',en,ur,ps,kind='heading')
def P(s,ur,en,ps,**m): add(s,f'p{len(s["paras"])+1}',en,ur,ps,**m)
def Q(s,ur,en,ps,u='p01',**k): add(s,f'q{len(s["paras"])+1}',en,ur,ps,role='question',exerciseId=f'urdu11-{u}-q',tab='exercise',**k)
def O(s,ur,en,ps,u='p01'): add(s,f'o{len(s["paras"])+1}',en,ur,ps,role='option',exerciseId=f'urdu11-{u}-q',tab='exercise')
def MC(s,q,vals,u='p01'):
    Q(s,*q,u=u)
    for a,e,v in zip(['الف','ب','ج','د'],['a','b','c','d'],vals):
        O(s,f'{a}) {v[0]}',f'({e}) {v[1]}',f'{a}) {v[2]}',u=u)
